-- Original191 lowercase source-kind domain, kept separate from derived source hooks.
INSERT INTO guard_fail(code) SELECT 'precondition_changed' WHERE EXISTS(SELECT 1 FROM credit_source_builds WHERE NOT(length(source_kind) BETWEEN 1 AND 64 AND substr(source_kind,1,1) GLOB '[a-z]' AND source_kind NOT GLOB '*[^a-z0-9_.-]*'));
CREATE TRIGGER credit_source_builds_kind_insert BEFORE INSERT ON credit_source_builds WHEN NOT(length(NEW.source_kind) BETWEEN 1 AND 64 AND substr(NEW.source_kind,1,1) GLOB '[a-z]' AND NEW.source_kind NOT GLOB '*[^a-z0-9_.-]*') BEGIN SELECT RAISE(ABORT,'Original source kind grammar'); END;
CREATE TRIGGER credit_source_builds_kind_update BEFORE UPDATE ON credit_source_builds WHEN NOT(length(NEW.source_kind) BETWEEN 1 AND 64 AND substr(NEW.source_kind,1,1) GLOB '[a-z]' AND NEW.source_kind NOT GLOB '*[^a-z0-9_.-]*') BEGIN SELECT RAISE(ABORT,'Original source kind grammar'); END;
